<?php
namespace Tests\Feature;
use App\Models\Product;use App\Models\User;use App\Services\AccountingReportService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\DB;use Tests\TestCase;
class ErpCommercialCompletionTest extends TestCase{use RefreshDatabase;private User$admin;protected function setUp():void{parent::setUp();$this->seed();$this->admin=User::factory()->create(['role'=>1,'force_change_password'=>false]);$this->actingAs($this->admin,'sanctum');}
 public function test_purchase_and_sale_units_persist_conversion_snapshots_and_base_stock():void{$p=Product::factory()->create();$box=DB::table('units')->where('name','box')->value('id');$strip=DB::table('units')->where('name','strip')->value('id');$this->postJson("/api/products/$p->id/units",['unit_id'=>$box,'base_quantity'=>20,'is_purchase_unit'=>true])->assertCreated();$stripDef=$this->postJson("/api/products/$p->id/units",['unit_id'=>$strip,'base_quantity'=>10,'sale_price'=>50,'is_sale_unit'=>true])->assertCreated()->json('data.id');$purchase=$this->postJson('/api/purchase-invoices',['provider_id'=>$this->provider(),'date'=>now()->toDateString(),'items'=>[['product_id'=>$p->id,'unit_id'=>$box,'batch_number'=>'UNIT-1','expire_date'=>now()->addYear()->toDateString(),'amount'=>5,'purchase_price'=>40,'selling_price'=>5]]])->assertCreated()->json('data.id');$this->postJson("/api/purchase-invoices/$purchase/post")->assertOk();$line=DB::table('prod_purch')->where('purchase_invoice_id',$purchase)->first();$this->assertEquals(5,$line->transaction_quantity);$this->assertEquals(20,$line->conversion_factor);$this->assertEquals(100,$line->base_quantity);$sale=$this->postJson('/api/sales-invoices',['customer_id'=>$this->customer(),'date'=>now()->toDateString(),'discount'=>0,'paid_amount'=>100,'payment_method'=>'cash','items'=>[['product_id'=>$p->id,'unit_id'=>$strip,'amount'=>2,'price'=>50,'discount'=>0]]])->assertCreated()->json('data.id');$saleLine=DB::table('prod_sales')->where('sales_invoice_id',$sale)->first();$this->assertEquals(20,$saleLine->base_quantity);$this->assertSame(80,(int)DB::table('product_batches')->where('product_id',$p->id)->value('quantity'));$this->putJson("/api/products/$p->id/units/$stripDef",['base_quantity'=>12])->assertConflict();$this->assertEquals(10,DB::table('product_units')->where('id',$stripDef)->value('base_quantity'));}
 public function test_discount_price_override_below_cost_and_credit_are_server_authorized():void{$p=Product::factory()->create();$batch=DB::table('product_batches')->insertGetId(['product_id'=>$p->id,'batch_number'=>'AUTH-1','expiry_date'=>now()->addYear(),'purchase_price'=>8,'sale_price'=>10,'quantity'=>10,'inventory_state'=>'available','created_at'=>now(),'updated_at'=>now()]);$customer=$this->customer();DB::table('customers')->where('id',$customer)->update(['credit_limit'=>5,'block_on_limit'=>true]);$cashier=User::factory()->create(['role'=>DB::table('roles')->where('name','Cashier')->value('id'),'force_change_password'=>false]);$this->actingAs($cashier,'sanctum')->postJson('/api/sales-invoices',['customer_id'=>$customer,'date'=>now()->toDateString(),'discount'=>0,'paid_amount'=>0,'payment_method'=>'cash','items'=>[['batch_id'=>$batch,'amount'=>1,'price'=>10,'discount_type'=>'fixed','discount_value'=>1,'discount_reason'=>'Promo']]])->assertForbidden();$this->actingAs($cashier,'sanctum')->postJson('/api/sales-invoices',['customer_id'=>$customer,'date'=>now()->toDateString(),'discount'=>0,'paid_amount'=>0,'payment_method'=>'cash','items'=>[['batch_id'=>$batch,'amount'=>1,'price'=>10,'discount'=>0]]])->assertConflict();$this->actingAs($this->admin,'sanctum')->postJson('/api/sales-invoices',['customer_id'=>$customer,'date'=>now()->toDateString(),'discount'=>0,'paid_amount'=>0,'payment_method'=>'cash','credit_override_reason'=>'Manager approval','items'=>[['batch_id'=>$batch,'amount'=>1,'price'=>7,'discount'=>0,'override_reason'=>'Clearance']]])->assertCreated();$this->assertDatabaseHas('audit_logs',['action_type'=>'credit_override','record_id'=>$customer]);$this->assertTrue(app(AccountingReportService::class)->trialBalance()['is_balanced']);}
 public function test_cashier_shift_expense_other_income_aging_and_numbers_are_authoritative():void{$branch=DB::table('branches')->where('code','MAIN')->value('id');$shift=$this->postJson('/api/cashier-shifts/open',['branch_id'=>$branch,'opening_cash'=>100])->assertCreated()->json('data.id');$expense=$this->postJson('/api/expenses',['amount'=>20,'payment_type'=>'cash','expense_date'=>now()->toDateString(),'branch_id'=>$branch,'description'=>'Utilities'])->assertCreated()->json('data');$income=$this->postJson('/api/other-incomes',['date'=>now()->toDateString(),'branch_id'=>$branch,'account_id'=>DB::table('accounts')->where('code','4200')->value('id'),'amount'=>30,'payment_method'=>'cash','description'=>'Delivery fee'])->assertCreated()->json('data');$this->assertStringStartsWith('EXP-', $expense['document_number']);$this->assertStringStartsWith('OIN-', $income['document_number']);$detail=$this->getJson("/api/cashier-shifts/$shift")->assertOk();$this->assertEquals(110,$detail->json('data.expected_cash'));$this->postJson("/api/cashier-shifts/$shift/close",['counted_cash'=>108])->assertOk()->assertJsonPath('data.difference',-2);$this->postJson("/api/cashier-shifts/$shift/close",['counted_cash'=>108])->assertConflict();$this->getJson('/api/accounting/reports/ar-aging')->assertOk()->assertJsonStructure(['data','meta']);$this->getJson('/api/accounting/reports/ap-aging')->assertOk();$this->assertTrue(app(AccountingReportService::class)->trialBalance()['is_balanced']);}
 public function test_package_prices_are_product_specific_and_returned_to_sale_ui():void
 {
  $panadol=Product::factory()->create(['barcode'=>'PANADOL-PACK']);$vitamin=Product::factory()->create(['barcode'=>'VIT-C-PACK']);$box=DB::table('units')->where('name','box')->value('id');$strip=DB::table('units')->where('name','strip')->value('id');
  $this->postJson("/api/products/$panadol->id/units",['unit_id'=>$strip,'base_quantity'=>10,'sale_price'=>5,'is_sale_unit'=>true])->assertCreated();
  $this->postJson("/api/products/$panadol->id/units",['unit_id'=>$box,'base_quantity'=>20,'sale_price'=>10,'is_sale_unit'=>true])->assertCreated();
  $this->postJson("/api/products/$vitamin->id/units",['unit_id'=>$box,'base_quantity'=>20,'sale_price'=>15,'is_sale_unit'=>true])->assertCreated();
  foreach([[$panadol,100],[$vitamin,100]] as [$product,$quantity])DB::table('product_batches')->insert(['product_id'=>$product->id,'batch_number'=>'PACK-'.$product->id,'expiry_date'=>now()->addYear(),'purchase_price'=>.2,'sale_price'=>.5,'quantity'=>$quantity,'inventory_state'=>'available','created_at'=>now(),'updated_at'=>now()]);
  $this->getJson('/api/product/barcode/PANADOL-PACK')->assertOk()->assertJsonPath('data.sale_units.0.sale_price',5)->assertJsonPath('data.sale_units.1.sale_price',10);
  $this->getJson('/api/product/barcode/VIT-C-PACK')->assertOk()->assertJsonPath('data.sale_units.0.sale_price',15);
 }
 public function test_multiline_package_sale_partial_cash_and_invoice_percentage_discount_are_authoritative():void
 {
  $customer=$this->customer();$box=DB::table('units')->where('name','box')->value('id');$strip=DB::table('units')->where('name','strip')->value('id');$a=Product::factory()->create();$b=Product::factory()->create();
  $this->postJson("/api/products/$a->id/units",['unit_id'=>$box,'base_quantity'=>20,'sale_price'=>10,'is_sale_unit'=>true]);$this->postJson("/api/products/$b->id/units",['unit_id'=>$strip,'base_quantity'=>10,'sale_price'=>8,'is_sale_unit'=>true]);
  foreach([[$a,100],[$b,100]] as [$product,$quantity])DB::table('product_batches')->insert(['product_id'=>$product->id,'batch_number'=>'MULTI-'.$product->id,'expiry_date'=>now()->addYear(),'purchase_price'=>.2,'sale_price'=>1,'quantity'=>$quantity,'inventory_state'=>'available','created_at'=>now(),'updated_at'=>now()]);
  $invoice=$this->postJson('/api/sales-invoices',['customer_id'=>$customer,'date'=>now()->toDateString(),'invoice_discount_type'=>'percentage','invoice_discount_value'=>10,'invoice_discount_reason'=>'Loyalty','paid_amount'=>10,'payment_method'=>'cash','items'=>[['product_id'=>$a->id,'unit_id'=>$box,'amount'=>2,'price'=>10,'discount_type'=>'fixed','discount_value'=>2,'discount_reason'=>'Promo'],['product_id'=>$b->id,'unit_id'=>$strip,'amount'=>1,'price'=>8,'discount'=>0]]])->assertCreated()->json('data.id');
  $sale=DB::table('sales_invoices')->find($invoice);$this->assertEquals(23.4,$sale->total_price);$this->assertEquals(2.6,$sale->discount);$this->assertSame('percentage',$sale->discount_type);$this->assertEquals(10,$sale->discount_value);$this->assertSame(2,DB::table('prod_sales')->where('sales_invoice_id',$invoice)->count());$this->assertEquals(40,DB::table('prod_sales')->where('sales_invoice_id',$invoice)->where('transaction_unit_id',$box)->sum('base_quantity'));
  $statement=app(AccountingReportService::class)->customerStatement($customer);$this->assertEquals(13.4,$statement['balance']);$this->assertTrue(app(AccountingReportService::class)->trialBalance()['is_balanced']);
 }
 public function test_sale_cheque_creates_pending_incoming_cheque_and_posts_to_cheque_receivable():void
 {
  $customer=$this->customer();$product=Product::factory()->create();DB::table('product_batches')->insert(['product_id'=>$product->id,'batch_number'=>'CHQ-SALE','expiry_date'=>now()->addYear(),'purchase_price'=>4,'sale_price'=>10,'quantity'=>10,'inventory_state'=>'available','created_at'=>now(),'updated_at'=>now()]);
  $invoice=$this->postJson('/api/sales-invoices',['customer_id'=>$customer,'date'=>now()->toDateString(),'discount'=>0,'paid_amount'=>6,'payment_method'=>'cheque','cheque_number'=>'IN-100','cheque_bank'=>'Test Bank','cheque_due_date'=>now()->addWeek()->toDateString(),'items'=>[['product_id'=>$product->id,'amount'=>1,'price'=>10,'discount'=>0]]])->assertCreated()->json('data.id');
  $this->assertDatabaseHas('checks',['check_number'=>'IN-100','status'=>'pending','direction'=>'in','reference_type'=>'sales_invoice','reference_id'=>$invoice,'customer_id'=>$customer,'amount'=>6]);
  $chequeAccount=DB::table('accounts')->where('code','1500')->value('id');$this->assertDatabaseHas('journal_entry_lines',['account_id'=>$chequeAccount,'side'=>'debit','amount'=>6]);$this->assertTrue(app(AccountingReportService::class)->trialBalance()['is_balanced']);
 }
 private function customer():int{return DB::table('customers')->insertGetId(['name'=>fake()->name(),'phone_num'=>fake()->unique()->numerify('######'),'city'=>'Test']);}private function provider():int{return DB::table('providers')->insertGetId(['name'=>fake()->company(),'phone_num'=>fake()->unique()->numerify('######'),'city'=>'Test']);}}
